<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';login_required();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=post_int('id');if(post('action')==='delete'&&$id){$pdo->prepare('DELETE FROM customer WHERE customer_id=?')->execute([$id]);flash('success','Customer deleted.');}redirect('customers.php');}
$q=post('q')?:($_GET['q']??'');$sql='SELECT * FROM customer';$p=[];if($q!==''){$sql.=' WHERE customer_firstname LIKE ? OR customer_lastname LIKE ? OR customer_TCno LIKE ? OR customer_email LIKE ?';$l="%$q%";$p=[$l,$l,$l,$l];}$sql.=' ORDER BY customer_id DESC';$s=$pdo->prepare($sql);$s->execute($p);$rows=$s->fetchAll();
page_header('Customers','customer');?>
<div class="page-head"><div><h1>Customers</h1><p class="muted">Guest records</p></div><a class="btn primary" href="customer.php">Add Customer</a></div><form class="toolbar"><input name="q" value="<?=e($q)?>" placeholder="Search by name, TC number or email"><button class="btn">Search</button></form>
<section class="card table-wrap"><table><thead><tr><th>ID</th><th>Full name</th><th>TC no</th><th>Telephone</th><th>Email</th><th>City</th><th>Country</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['customer_id']?></td><td><?=e($r['customer_firstname'].' '.$r['customer_lastname'])?></td><td><?=e($r['customer_TCno'])?></td><td><?=e($r['customer_telephone'])?></td><td><?=e($r['customer_email'])?></td><td><?=e($r['customer_city'])?></td><td><?=e($r['customer_country'])?></td><td class="actions"><a href="customer_edit.php?id=<?=$r['customer_id']?>">Edit</a><form method="post" onsubmit="return confirm('Are you sure?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['customer_id']?>"><button class="danger-link">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="empty">No customers found.</td></tr><?php endif;?></tbody></table></section>
<?php page_footer();?>
